from pathlib import Path
import os,subprocess,shutil,json,pwd
target=Path('/home/ubuntu/.cache/node-gyp')
def call(a,t=14):
 return subprocess.run(a,capture_output=True,text=True,timeout=t)
def st(n):
 return call(['systemctl','is-active',n+'.service'],8).stdout.strip()
def bots():
 q=call(['pm2','jlist'],16)
 if q.returncode:raise RuntimeError('Cannot inspect PM2')
 return {a.get('name'):{'status':(a.get('pm2_env') or {}).get('status'),'pid':a.get('pid')} for a in json.loads(q.stdout) if a.get('name') in ('iptvpn_bot','telegram-robot-leads')}
services=['fadego-staging','lowcost-europa','pink-iptv-backend','pink-vpn','nginx','postgresql@16-main','pm2-root']
state={n:st(n) for n in services}
before=bots()
if any(x!='active' for x in state.values()) or any(before.get(n,{}).get('status')!='online' for n in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Services or Telegram apps not healthy')
if not target.is_dir() or target.is_symlink() or target.stat().st_uid!=pwd.getpwnam('ubuntu').pw_uid:
 raise RuntimeError('Unexpected node-gyp cache ownership')
if target.parent!=Path('/home/ubuntu/.cache') or target.parent.is_symlink():raise RuntimeError('Node-gyp cache parent invalid')
for proc in Path('/proc').iterdir():
 if not proc.name.isdigit():continue
 try:
  raw=(proc/'cmdline').read_bytes().replace(b'\0',b' ').decode(errors='replace')
  if 'python3 -' not in raw and any(s in raw for s in ('node-gyp rebuild','node-gyp configure','npm install','npm ci')):
   raise RuntimeError('Node/npm build running')
  cwd=os.readlink(proc/'cwd')
  if cwd==str(target) or cwd.startswith(str(target)+'/'):raise RuntimeError('Process CWD uses node-gyp cache')
  for fd in (proc/'fd').iterdir():
   try:
    path=os.readlink(fd)
    if path==str(target) or path.startswith(str(target)+'/'):raise RuntimeError('Open FD uses node-gyp cache')
   except OSError:pass
 except (OSError,PermissionError):pass
measure=call(['du','-x','-s','-B1',str(target)],42)
if measure.returncode:raise RuntimeError('Cannot measure cache')
cache_size=int(measure.stdout.split()[0])
free_before=shutil.disk_usage('/').free
shutil.rmtree(target)
if target.exists() or target.is_symlink():raise RuntimeError('Node-gyp cache remains after cleanup')
gain=shutil.disk_usage('/').free-free_before
if any(st(n)!=x for n,x in state.items()):raise RuntimeError('Service state changed')
if bots()!=before:raise RuntimeError('Telegram process changed')
print('NODE_GYP_CACHE_BYTES_REMOVED='+str(cache_size))
print('DISK_FREE_GAIN_BYTES='+str(gain))
print('PROJECT_DEPENDENCIES_KEPT=YES')
print('REA_CACHES_KEPT=YES')
print('ACTIVE_SERVICES_AND_BOTS_UNCHANGED=YES')
print('NODE_GYP_DOWNLOAD_CACHE_CLEANUP=PASS')
PY
